<main class="melhorias-page"><header class="page-heading"><div><div class="breadcrumb">Insight CX <span>/</span> Melhorias</div><h1>Ações de melhoria</h1><p>Acompanhe providências e transforme feedbacks em evolução.</p></div><button class="primary-button" type="button" data-open-modal>＋ Nova ação</button></header>
<section class="toolbar"><label class="search-box"><span>⌕</span><input type="search" id="buscaAcao" placeholder="Buscar ação ou cliente..."></label><select id="filtroPrioridade" class="filter-select"><option value="">Todas as prioridades</option><option>Alta</option><option>Média</option><option>Baixa</option></select><div class="board-summary"><span><i class="dot overdue"></i><strong id="acoesAtrasadas">0</strong> atrasadas</span><span><strong id="totalAcoes">0</strong> ações no total</span></div></section>
<section class="kanban-board" id="kanbanBoard"></section></main>
<div class="modal-backdrop" id="modalAcao" aria-hidden="true"><section class="action-modal" role="dialog" aria-modal="true"><header><div><small>GESTÃO DE MELHORIAS</small><h2 id="modalTitle">Nova ação</h2></div><button type="button" class="close-modal" data-close-modal>×</button></header><form id="formAcao"><input type="hidden" id="campoId"><label>Título da ação *<input id="campoTitulo" required maxlength="160"></label><label>Cliente<input id="campoCliente" maxlength="160"></label><div class="form-row"><label>Feedback relacionado<input id="campoFeedback"></label><label>Prioridade<select id="campoPrioridade"><option>Baixa</option><option selected>Média</option><option>Alta</option></select></label></div><label>Providência planejada<input id="campoProvidencia"></label><div class="form-row"><label>Responsável<input id="campoResponsavel"></label><label>Prazo<input type="date" id="campoPrazo"></label></div><label>Descrição<textarea id="campoDescricao" rows="3"></textarea></label><label>Status<select id="campoStatus"><option>Pendente</option><option>Em análise</option><option>Em andamento</option><option>Concluído</option></select></label><footer><button type="button" class="secondary-button" data-close-modal>Cancelar</button><button class="primary-button" type="submit">Salvar ação</button></footer></form></section></div><script src="assets/js/melhorias.js"></script>
